import sys

def query(u, v):
    print(f'? {u} {v}', flush=True)
    return int(sys.stdin.readline().strip())

n = int(sys.stdin.readline().strip())
edges = [tuple(map(int, sys.stdin.readline().split())) for _ in range(n-1)]

queries = 0
max_queries = n // 2

# Find a leaf node
leaf = None
for u, v in edges:
    if leaf is None:
        leaf = u
    elif leaf == u:
        leaf = v
    if queries >= max_queries:
        break
    lca = query(1, u)
    if lca != 1:
        leaf = u
    else:
        lca = query(1, v)
        if lca != 1:
            leaf = v
    queries += 1

# Now we have a leaf node, find the root
current = leaf
parent = None
while queries < max_queries:
    found_root = True
    for u, v in edges:
        if u == current:
            neighbor = v
        elif v == current:
            neighbor = u
        else:
            continue
        lca = query(1, neighbor)
        queries += 1
        if lca == current:
            parent = neighbor
            current = parent
            found_root = False
            break
    if found_root:
        break

print(f'! {current}')
